export class MedalComponent implements OnInit {
  constructor() {}

  @Input()
  class: string;

  @Input()
  title: string;

  @Input()
  main_color: string;

  @Input()
  accent_color: string;

  get main_color_style() {
    if (this.main_color.match(/^[a-zA-Z]+$/gm)) {
      return { color: `var(--${this.main_color})` };
    } else {
      return { color: this.main_color };
    }
  }

  get accent_color_style() {
    if (this.accent_color) {
      return { color: this.accent_color };
    } else {
      return {
        filter: "brightness(0.7)",
        ...this.main_color_style,
      };
    }
  }

  ngOnInit(): void {}
}
